    /// <summary>Validates the transport flag and the domain status, returning the
    /// payload envelope on success.</summary>
    private static JsonNode Unwrap(PlayerResponse resp)
    {
        if (!resp.Ok)
            throw new GameBackendTransportException(resp.Error);
        JsonNode payload = resp.Payload
            ?? throw new GameBackendTransportException("transport reported ok but no payload envelope");
        JsonNode statusNode = payload["status"]
            ?? throw new GameBackendTransportException("response envelope missing 'status'");
        Status status = statusNode.Deserialize<Status>(JsonOpts);
        if (status != Status.Ok)
            throw new GameBackendStatusException(status, payload["err"]?.GetValue<string>());
        return payload;
    }
